from dataclasses import InitVar, dataclass
from typing import overload


@dataclass
class Record:
    value: InitVar[int]

    @overload
    def __post_init__(self, value: int) -> None: ...
    @overload
    def __post_init__(self, value: int, extra: str) -> None: ...
    def __post_init__(self, value: int, extra: str = "") -> None:
        print(value)


