from typing import overload
class Base:
    def hook(self, value: int) -> None:
        print(value)
class Record(Base):
    @overload
    def hook(self, value: int) -> None: ...
    @overload
    def hook(self, value: str) -> None: ...
    def hook(self, value: int | str) -> None:
        print(value)
